require_once dirname(__DIR__,2).'/config/config.php';require_once dirname(__DIR__,2).'/config/database.php';require_once dirname(__DIR__,2).'/config/functions.php';require_once dirname(__DIR__,2).'/config/session.php';require_once dirname(__DIR__,2).'/config/family_scope.php';Session::start();if(!Session::isLoggedIn()){header('Location: '.APP_URL.'index.php');exit();}$role=Session::getUserRole();if(!in_array($role,['admin','vice_general_manager','general_manager','supervisor','accountant'],true)){header('Location: '.APP_URL.'index.php');exit();}$pageTitle=t('sponsorships.title');$active='sponsorships';$id=(int)($_GET['id']??0);$sp=dbFetchOne("SELECT sp.*,s.full_name AS sponsor_name,s.sponsor_code,s.id AS sponsor_id,fc.id AS child_id,fc.child_name,f.mother_name,f.family_code,f.id AS family_id FROM sponsorships sp JOIN sponsors s ON s.id=sp.sponsor_id JOIN family_children fc ON fc.id=sp.child_id JOIN families f ON f.id=fc.family_id WHERE sp.id=?",[$id]);if(!$sp){flash('error',t('common.no_data'));redirect('modules/sponsorships/index.php');}$canManage=in_array($role,['admin','vice_general_manager'],true);if($role==='supervisor'){$uid=Session::getUserId();$allowed=((int)($sp['supervisor_id']??0)===$uid);if(!$allowed){$matrixRows=dbFetchAll("SELECT gender FROM supervisor_letters WHERE supervisor_id=? AND letter_id=(SELECT first_letter_id FROM sponsors WHERE id=? LIMIT 1)",[$uid,(int)$sp['sponsor_id']]);$sg=strtolower(trim((string)($sp['sponsor_gender']??'')));$sg=$sg==='m'||$sg==='male'||$sg==='ذكر'?'male':($sg==='f'||$sg==='female'||$sg==='أنثى'||$sg==='انثى'?'female':'other');foreach($matrixRows as $mr){$mg=strtolower(trim((string)($mr['gender']??'')));$mg=$mg==='m'||$mg==='male'||$mg==='ذكر'?'male':($mg==='f'||$mg==='female'||$mg==='أنثى'||$mg==='انثى'?'female':($mg==='both'||$mg==='all'||$mg==='كلاهما'||$mg==='الكل'?'both':'other'));if($mg==='both'||$mg===$sg){$allowed=true;break;}}}if(!$allowed){flash('error',t('common.no_data'));redirect('modules/sponsorships/index.php');}$canManage=true;}
if($_SERVER['REQUEST_METHOD']==='POST'&&$canManage){if(!verify_csrf())flash('error',t('auth.enter_credentials'));else{$action=$_POST['action']??'';$today=date('Y-m-d');$old=$sp['status'];$new=$old;if($action==='pause'&&$old==='active'){$new='paused';dbExecute("UPDATE sponsorships SET status='paused',pause_reason=?,pause_start_date=?,updated_by=? WHERE id=?",[trim($_POST['pause_reason']??'')?:null,$today,Session::getUserId(),$id]);}elseif($action==='resume'&&$old==='paused'){$new='active';dbExecute("UPDATE sponsorships SET status='active',pause_end_date=?,updated_by=? WHERE id=?",[$today,Session::getUserId(),$id]);}elseif($action==='complete'&&in_array($old,['active','paused'],true)){$new='completed';dbExecute("UPDATE sponsorships SET status='completed',end_date=?,updated_by=? WHERE id=?",[$today,$sp['child_id']]);dbExecute("UPDATE family_children SET match_status='unmatched' WHERE id=?",[$sp['child_id']]);}elseif($action==='cancel'&&$old!=='cancelled'){$new='cancelled';dbExecute("UPDATE sponsorships SET status='cancelled',end_date=?,updated_by=? WHERE id=?",[$today,Session::getUserId(),$id]);dbExecute("UPDATE family_children SET match_status='lost_sponsor' WHERE id=?",[$sp['child_id']]);}if($new!==$old){dbExecute("INSERT INTO audit_log (user_id,action,entity_type,entity_id,old_values,new_values,ip_address,user_agent) VALUES (?,?,'sponsorships',?,?,?,?,?)",[Session::getUserId(),$action==='pause'?'PAUSE':($action==='resume'?'RESUME':'UPDATE'),$id,json_encode(['status'=>$old],JSON_UNESCAPED_UNICODE),json_encode(['status'=>$new,'reason'=>$_POST['pause_reason']??null],JSON_UNESCAPED_UNICODE),$_SERVER['REMOTE_ADDR']??'',$_SERVER['HTTP_USER_AGENT']??'']);$statusKey=['active'=>'common.active','paused'=>'common.paused','completed'=>'common.completed','cancelled'=>'common.cancelled'][$new]??null;flash('success',$statusKey?t('common.status').': '.t($statusKey):t('common.save'));header('Location: '.APP_URL.'modules/sponsorships/view.php?id='.$id);exit();}}}
$transactions=dbFetchAll("SELECT t.id,t.transaction_code,t.amount,t.transaction_date,t.payment_method,t.status,t.receipt_number FROM transactions t WHERE t.sponsorship_id=? ORDER BY t.transaction_date DESC,t.id DESC",[$id]);$totalPaid=0;foreach($transactions as $t)if($t['status']==='posted')$totalPaid+=(float)$t['amount'];include dirname(__DIR__,2).'/includes/header.php'; ?>
